    "contest": null,
    "solution": "Strategy: Let Snorlax age in 2018 be s; Mewtwo 2s; Raichu 2s+7. Two years ago Raichu was 5 times Snorlax: 2s+5=5(s−2) → 2s+5=5s−10 → 15=3s → s=5. Raichu age 17 in 2018 → made in 2001.",
