    "sourceTitle": "IMC 2017 Grade 6 (Russian School of Mathematics International Math Contest)",
    "year": "2017",
    "contest": null,
    "solution": "Strategy: Let s be the number of steps. Up time s/3, down s/2, and s/2−s/3=25 → s/6=25 → s=150.",
    "schema": "v2"
