    "contest": 2,
    "solution": "Strategy: House numbers form an arithmetic sequence 13, 17, …, 221 with common difference 4. Then 13+(n−1)×4=221 ⇒ (n−1)×4=208 ⇒ n−1=52 ⇒ n=53. Answer is 53.",
